# PR Diff Truncated

Original size: 12095 characters.
Kept: first 7800 and last 4200 characters.

The full diff is available in the checked-out PR branch. Use `git diff` or CodeGraph for focused source navigation instead of relying only on this file.

```diff
diff --git a/vendor/dart_tui/lib/src/key_buffer_parser.dart b/vendor/dart_tui/lib/src/key_buffer_parser.dart
index c1afc76cc8..e19ac572b9 100644
--- a/vendor/dart_tui/lib/src/key_buffer_parser.dart
+++ b/vendor/dart_tui/lib/src/key_buffer_parser.dart
@@ -167,14 +167,46 @@ TeaKey? parseKeyFromBuffer(List<int> buffer) {
     }
   }

-  // If we're here, it might be a partial UTF-8 sequence or invalid.
-  // UTF-8 lead bytes: 110xxxxx (2 bytes), 1110xxxx (3 bytes), 11110xxx (4 bytes).
-  if (b0 & 0x80 == 0) {
-    // Should have been handled by utf8.decode(len=1) but for safety:
+  // If we're here, it could be a PARTIAL UTF-8 sequence or something that can
+  // never decode. The second case is not hypothetical: a Windows console in a
+  // legacy OEM code page delivers a Cyrillic keystroke as ONE byte (0xEF for
+  // 'п'), which looks like a 3-byte UTF-8 lead but is never followed by
+  // continuations. Waiting for them wedged the WHOLE input stream — the buffer
+  // only grew and no key was ever emitted again, so the user could not type
+  // Russian at all (fa issue #1973 follow-up). Wait only while the head can
+  // still complete.
+  final expected = _utf8SequenceLength(b0);
+  if (expected == 0) {
+    // Not a UTF-8 lead byte: a bare continuation byte or 0xF8+. Junk — drop it.
     buffer.removeAt(0);
-    return TeaKey(code: KeyCode.rune, text: String.fromCharCode(b0));
+    return const TeaKey(code: KeyCode.unknown);
+  }
+  final lookahead = expected < buffer.length ? expected : buffer.length;
+  var malformed = false;
+  for (var i = 1; i < lookahead; i++) {
+    if ((buffer[i] & 0xC0) != 0x80) {
+      malformed = true; // a non-continuation inside the promised window
+      break;
+    }
   }
+  if (!malformed && buffer.length < expected) {
+    return null; // genuinely partial: the rest of the character is in flight
+  }
+  // The head can never complete here: consume ONE byte so typing recovers
+  // instead of stalling. The byte surfaces as a Latin-1 rune rather than
+  // vanishing silently.
+  buffer.removeAt(0);
+  return TeaKey(code: KeyCode.rune, text: String.fromCharCode(b0));
+}

-  // Wait for more bytes if it looks like a lead byte
-  return null;
+/// How many bytes a UTF-8 sequence starting with [b] occupies (1 for ASCII),
+/// or 0 when [b] cannot start one. The parser uses it to tell a genuinely
+/// partial character (wait for more bytes) from a head that can never decode
+/// (consume it, or the stream stalls — see [parseKeyFromBuffer]).
+int _utf8SequenceLength(int b) {
+  if (b < 0x80) return 1;
+  if ((b & 0xE0) == 0xC0) return 2;
+  if ((b & 0xF0) == 0xE0) return 3;
+  if ((b & 0xF8) == 0xF0) return 4;
+  return 0;
 }
diff --git a/vendor/dart_tui/lib/src/windows_terminal.dart b/vendor/dart_tui/lib/src/windows_terminal.dart
index a2edd568b3..e375ca02aa 100644
--- a/vendor/dart_tui/lib/src/windows_terminal.dart
+++ b/vendor/dart_tui/lib/src/windows_terminal.dart
@@ -23,8 +23,16 @@ typedef _GetConsoleModeC = Int32 Function(IntPtr, Pointer<Uint32>);
 typedef _GetConsoleModeD = int Function(int, Pointer<Uint32>);
 typedef _SetConsoleModeC = Int32 Function(IntPtr, Uint32);
 typedef _SetConsoleModeD = int Function(int, int);
+typedef _GetConsoleCpC = Uint32 Function();
+typedef _GetConsoleCpD = int Function();
+typedef _SetConsoleCpC = Int32 Function(Uint32);
+typedef _SetConsoleCpD = int Function(int);
+
+/// The UTF-8 code page: what `dart_tui`'s decoder expects on the wire.
+const int _utf8CodePage = 65001;

 int? _savedMode;
+int? _savedCodePage;

 /// Puts the Windows console **input** handle into raw virtual-terminal mode so
 /// arrow keys, Esc, Shift+Tab, function keys and the mouse arrive as the escape
@@ -64,6 +72,26 @@ void enableWindowsVtInput() {
             _enableEchoInput |
             _enableProcessedInput);
     setConsoleMode(handle, next);
+    // The console hands input over in its INPUT code page: under a legacy OEM
+    // page (866/1251 on a Russian Windows) a Cyrillic keystroke is a single
+    // byte like 0xEF, which `key_buffer_parser.dart` cannot decode as UTF-8 —
+    // and a stream stuck on such a byte swallows every later keystroke too
+    // ("cannot type Russian at all"). UTF-8 makes non-ASCII arrive in the
+    // bytes the decoder already understands.
+    try {
+      final getConsoleCP = k32
+          .lookupFunction<_GetConsoleCpC, _GetConsoleCpD>('GetConsoleCP');
+      final setConsoleCP = k32
+          .lookupFunction<_SetConsoleCpC, _SetConsoleCpD>('SetConsoleCP');
+      final previousCp = getConsoleCP();
