        0x46 => const TeaKey(code: KeyCode.end),
        0x50 => const TeaKey(code: KeyCode.f1),
        0x51 => const TeaKey(code: KeyCode.f2),
        0x52 => const TeaKey(code: KeyCode.f3),
        0x53 => const TeaKey(code: KeyCode.f4),
        _ => null,
      };
      buffer.removeRange(0, 3);
      return key ?? const TeaKey(code: KeyCode.unknown);
    }

    // Alt+Left: ESC b
    if (b1 == 0x62) {
      buffer.removeRange(0, 2);
      return const TeaKey(code: KeyCode.left, modifiers: {KeyMod.alt});
    }
    // Alt+Right: ESC f
    if (b1 == 0x66) {
      buffer.removeRange(0, 2);
      return const TeaKey(code: KeyCode.right, modifiers: {KeyMod.alt});
    }
    // Alt+Backspace: ESC DEL
    if (b1 == 0x7f) {
      buffer.removeRange(0, 2);
      return const TeaKey(code: KeyCode.backspace, modifiers: {KeyMod.alt});
    }
    // Alt+Enter: ESC CR (terminals without kitty/modifyOtherKeys support,
    // e.g. Warp's legacy TUI passthrough) and ESC LF — the same wire after
    // a kernel line discipline with ICRNL still on translated the CR before
    // the app read it (fa issue #77; the fallback for hosts that reset
    // termios under us or where stty is unavailable). Neither byte pair has
    // any other standard meaning.
    if (b1 == 0x0d || b1 == 0x0a) {
      buffer.removeRange(0, 2);
      return const TeaKey(code: KeyCode.enter, modifiers: {KeyMod.alt});
    }
    // Double Escape: two presses landing in one read chunk used to fall
    // into the `unknown` fallthrough below and BOTH presses were swallowed
    // — during a streaming run the abort Esc never fired and the TUI looked
    // frozen (fa issue #46). ESC ESC is not any terminal's sequence for
    // anything else: consume only the FIRST byte and emit the Escape key;
    // the remaining byte parses as a lone ESC on the next pass, delivered
    // by the Program's lone-escape timer.
    if (b1 == 0x1b) {
      buffer.removeAt(0);
      return const TeaKey(code: KeyCode.escape);
    }

    buffer.removeRange(0, 2);
    return const TeaKey(code: KeyCode.unknown);
  }

  // DEL / Backspace
  if (b0 == 0x7f) {
    buffer.removeAt(0);
    return const TeaKey(code: KeyCode.backspace);
  }

  // Other non-printable controls
  if (b0 == 0x00 || (b0 >= 0x1c && b0 <= 0x1f)) {
    buffer.removeAt(0);
    return const TeaKey(code: KeyCode.unknown);
  }

  // Multi-byte UTF-8 or Printable ASCII
  // Try to decode as much as possible from the start of the buffer.
  // Cap the run at the first CONTROL byte: a burst read delivering
  // "text\r" (or "text\n") in one chunk must not swallow the Enter into
  // the text run — the control byte belongs to the next key.
  var maxRun = 0;
  while (maxRun < buffer.length && maxRun < 4) {
    final b = buffer[maxRun];
    if (b < 0x20 || b == 0x7f) break;
    maxRun++;
  }
  for (var len = maxRun; len >= 1; len--) {
    try {
      final decoded = utf8.decode(buffer.sublist(0, len));
      buffer.removeRange(0, len);
      return TeaKey(code: KeyCode.rune, text: decoded);
    } catch (_) {
      // Continue trying shorter lengths or wait for more bytes
    }
  }

  // If we're here, it could be a PARTIAL UTF-8 sequence or something that can
  // never decode. The second case is not hypothetical: a Windows console in a
  // legacy OEM code page delivers a Cyrillic keystroke as ONE byte (0xEF for
  // 'п'), which looks like a 3-byte UTF-8 lead but is never followed by
  // continuations. Waiting for them wedged the WHOLE input stream — the buffer
  // only grew and no key was ever emitted again, so the user could not type
  // Russian at all (fa issue #1973 follow-up). Wait only while the head can
  // still complete.
  final expected = _utf8SequenceLength(b0);
  if (expected == 0) {
    // Not a UTF-8 lead byte: a bare continuation byte or 0xF8+. Junk — drop it.
    buffer.removeAt(0);
    return const TeaKey(code: KeyCode.unknown);
  }
  final lookahead = expected < buffer.length ? expected : buffer.length;
  var malformed = false;
  for (var i = 1; i < lookahead; i++) {
    if ((buffer[i] & 0xC0) != 0x80) {
      malformed = true; // a non-continuation inside the promised window
      break;
    }
  }
  if (!malformed && buffer.length < expected) {
    return null; // genuinely partial: the rest of the character is in flight
  }
  // The head can never complete here: consume ONE byte so typing recovers
  // instead of stalling. The byte surfaces as a Latin-1 rune rather than
  // vanishing silently.
  buffer.removeAt(0);
  return TeaKey(code: KeyCode.rune, text: String.fromCharCode(b0));
}

/// How many bytes a UTF-8 sequence starting with [b] occupies (1 for ASCII),
/// or 0 when [b] cannot start one. The parser uses it to tell a genuinely
/// partial character (wait for more bytes) from a head that can never decode
/// (consume it, or the stream stalls — see [parseKeyFromBuffer]).
int _utf8SequenceLength(int b) {
  if (b < 0x80) return 1;
  if ((b & 0xE0) == 0xC0) return 2;
  if ((b & 0xF0) == 0xE0) return 3;
  if ((b & 0xF8) == 0xF0) return 4;
  return 0;
}

// coverage:ignore-file
// Windows-only console (Win32 FFI) code. Unreachable on the CI runners
// (macOS/Linux), so it is excluded from the coverage denominator rather than
// force-tested with brittle platform mocks.
import 'dart:ffi';
import 'dart:io';

import 'package:ffi/ffi.dart';

// Windows console input-mode flags (consoleapi / wincon.h).
const int _enableProcessedInput = 0x0001;
const int _enableLineInput = 0x0002;
const int _enableEchoInput = 0x0004;
const int _enableMouseInput = 0x0010;
const int _enableQuickEditMode = 0x0040;
const int _enableExtendedFlags = 0x0080;
const int _enableVirtualTerminalInput = 0x0200;
const int _stdInputHandle = 0xFFFFFFF6; // (DWORD)-10

typedef _GetStdHandleC = IntPtr Function(Uint32);
typedef _GetStdHandleD = int Function(int);
typedef _GetConsoleModeC = Int32 Function(IntPtr, Pointer<Uint32>);
typedef _GetConsoleModeD = int Function(int, Pointer<Uint32>);
typedef _SetConsoleModeC = Int32 Function(IntPtr, Uint32);
typedef _SetConsoleModeD = int Function(int, int);
typedef _GetConsoleCpC = Uint32 Function();
typedef _GetConsoleCpD = int Function();
typedef _SetConsoleCpC = Int32 Function(Uint32);
typedef _SetConsoleCpD = int Function(int);

/// The UTF-8 code page: what `dart_tui`'s decoder expects on the wire.
const int _utf8CodePage = 65001;

int? _savedMode;
int? _savedCodePage;

/// Puts the Windows console **input** handle into raw virtual-terminal mode so
/// arrow keys, Esc, Shift+Tab, function keys and the mouse arrive as the escape
/// sequences [TerminalInputDecoder] understands.
///
/// Flipping Dart's `stdin.lineMode`/`echoMode` alone is not enough on Windows:
/// it leaves the console in legacy input mode, where those events never reach
/// the byte stream at all (only plain ASCII does). Enabling
/// `ENABLE_VIRTUAL_TERMINAL_INPUT` is what makes them work; clearing
/// `ENABLE_QUICK_EDIT_MODE` is what lets mouse clicks through instead of being
/// captured as text selection, and clearing `ENABLE_PROCESSED_INPUT` delivers
/// Ctrl+C as a byte (matching Unix raw mode) rather than a console signal.
///
/// No-op on non-Windows platforms or when stdin is not a real console. Call it
/// while entering raw mode; the previous mode is saved for [restoreWindowsVtInput].
void enableWindowsVtInput() {
  if (!Platform.isWindows) return;
  final k32 = DynamicLibrary.open('kernel32.dll');
  final getStdHandle =
      k32.lookupFunction<_GetStdHandleC, _GetStdHandleD>('GetStdHandle');
  final getConsoleMode =
      k32.lookupFunction<_GetConsoleModeC, _GetConsoleModeD>('GetConsoleMode');
  final setConsoleMode =
      k32.lookupFunction<_SetConsoleModeC, _SetConsoleModeD>('SetConsoleMode');

  final handle = getStdHandle(_stdInputHandle);
  final modePtr = calloc<Uint32>();
  try {
    if (getConsoleMode(handle, modePtr) == 0) return; // not a console
    _savedMode ??= modePtr.value;
    final next = (modePtr.value |
            _enableVirtualTerminalInput |
            _enableExtendedFlags |
            _enableMouseInput) &
        ~(_enableQuickEditMode |
            _enableLineInput |
            _enableEchoInput |
            _enableProcessedInput);
    setConsoleMode(handle, next);
    // The console hands input over in its INPUT code page: under a legacy OEM
    // page (866/1251 on a Russian Windows) a Cyrillic keystroke is a single
    // byte like 0xEF, which `key_buffer_parser.dart` cannot decode as UTF-8 —
    // and a stream stuck on such a byte swallows every later keystroke too
    // ("cannot type Russian at all"). UTF-8 makes non-ASCII arrive in the
    // bytes the decoder already understands.
    try {
      final getConsoleCP = k32
          .lookupFunction<_GetConsoleCpC, _GetConsoleCpD>('GetConsoleCP');
      final setConsoleCP = k32
          .lookupFunction<_SetConsoleCpC, _SetConsoleCpD>('SetConsoleCP');
      final previousCp = getConsoleCP();
      if (previousCp != 0 && previousCp != _utf8CodePage) {
        _savedCodePage ??= previousCp;
        setConsoleCP(_utf8CodePage);
      }
    } on Object {
      // Older Windows / not a real console: the parser's recovery path below
      // still keeps the input stream alive.
    }
  } finally {
    calloc.free(modePtr);
  }
}

/// Restores the console input mode captured by the first [enableWindowsVtInput]
/// call. No-op on non-Windows platforms or if it was never enabled.
void restoreWindowsVtInput() {
  if (!Platform.isWindows) return;
  final savedCp = _savedCodePage;
  if (savedCp != null) {
    try {
      DynamicLibrary.open('kernel32.dll')
          .lookupFunction<_SetConsoleCpC, _SetConsoleCpD>('SetConsoleCP')(savedCp);
    } on Object {
      // Best effort: never block the teardown on a console that went away.
    }
    _savedCodePage = null;
  }
  final saved = _savedMode;
  if (saved == null) return;
  final k32 = DynamicLibrary.open('kernel32.dll');
  final getStdHandle =
      k32.lookupFunction<_GetStdHandleC, _GetStdHandleD>('GetStdHandle');
  final setConsoleMode =
      k32.lookupFunction<_SetConsoleModeC, _SetConsoleModeD>('SetConsoleMode');
  setConsoleMode(getStdHandle(_stdInputHandle), saved);
  _savedMode = null;
}

import 'dart:convert';

import 'key_buffer_parser.dart';
import 'kitty_keyboard.dart';
import 'msg.dart';

final class TerminalInputDecoder {
  final List<int> _buffer = <int>[];
  final StringBuffer _pasteBuffer = StringBuffer();
  bool _inPaste = false;

  List<Msg> feed(List<int> data) {
    _buffer.addAll(data);
    final out = <Msg>[];

    while (true) {
      if (_inPaste) {
        final endMatch = _matchesPrefix(_buffer, _pasteEnd);
        if (endMatch == _PrefixMatch.partial) break;
        if (endMatch == _PrefixMatch.full) {
          _consume(_pasteEnd.length);
          out.add(PasteMsg(_pasteBuffer.toString()));
          out.add(PasteEndMsg());
          _pasteBuffer.clear();
          _inPaste = false;
          continue;
        }

        if (_buffer.isEmpty) break;
        _pasteBuffer.writeCharCode(_buffer.removeAt(0));
        continue;
      }

      final pasteStartMatch = _matchesPrefix(_buffer, _pasteStart);
      if (pasteStartMatch == _PrefixMatch.partial) break;
      if (pasteStartMatch == _PrefixMatch.full) {
        _consume(_pasteStart.length);
        _inPaste = true;
        out.add(PasteStartMsg());
        continue;
      }

      final focusInMatch = _matchesPrefix(_buffer, _focusIn);
      if (focusInMatch == _PrefixMatch.partial) break;
      if (focusInMatch == _PrefixMatch.full) {
        _consume(_focusIn.length);
        out.add(FocusMsg());
        continue;
      }

      final focusOutMatch = _matchesPrefix(_buffer, _focusOut);
      if (focusOutMatch == _PrefixMatch.partial) break;
      if (focusOutMatch == _PrefixMatch.full) {
        _consume(_focusOut.length);
        out.add(BlurMsg());
        continue;
      }

      final osc = _tryParseOsc(_buffer);
      if (osc == _ParseState.partial) break;
      if (osc case _ParsedMessages(:final consumed, :final msgs)) {
        _consume(consumed);
        out.addAll(msgs);
        continue;
      }

      final dcs = _tryParseDcs(_buffer);
      if (dcs == _ParseState.partial) break;
      if (dcs case _ParsedMessages(:final consumed, :final msgs)) {
        _consume(consumed);
        out.addAll(msgs);
        continue;
      }

      final csi = _tryParseCsi(_buffer);
      if (csi == _ParseState.partial) break;
      if (csi case _ParsedMessages(:final consumed, :final msgs)) {
        _consume(consumed);
        out.addAll(msgs);
        continue;
      }

      final TeaKey? key = parseKeyFromBuffer(_buffer);
      if (key != null) {
        out.add(KeyPressMsg(key));
        continue;
      }

      break;
    }

    return out;
  }

  /// Whether the decoder is holding a single `ESC` byte that might be either a
  /// lone Escape key or the start of a sequence (e.g. arrow keys) not yet read.
  ///
  /// The [Program] schedules a short timer after input; if no further bytes
  /// arrive, it calls [takeLoneEscapeIfStillPending] to emit [KeyPressMsg] for
  /// Escape without breaking split `ESC [`… sequences across stdin chunks.
  bool get hasPendingLoneEscape =>
      !_inPaste && _buffer.length == 1 && _buffer[0] == 0x1b;

  /// If [hasPendingLoneEscape] is still true, consume the byte and return a
  /// single [KeyPressMsg] for Escape; otherwise returns an empty list.
  List<Msg> takeLoneEscapeIfStillPending() {
    if (!hasPendingLoneEscape) return const <Msg>[];
    _buffer.clear();
    return <Msg>[KeyPressMsg(const TeaKey(code: KeyCode.escape))];
  }

  void _consume(int count) {
    _buffer.removeRange(0, count);
  }
}

const List<int> _pasteStart = <int>[0x1b, 0x5b, 0x32, 0x30, 0x30, 0x7e];
const List<int> _pasteEnd = <int>[0x1b, 0x5b, 0x32, 0x30, 0x31, 0x7e];
const List<int> _focusIn = <int>[0x1b, 0x5b, 0x49];
const List<int> _focusOut = <int>[0x1b, 0x5b, 0x4f];

sealed class _ParseResult {
  const _ParseResult();
}

final class _ParseState extends _ParseResult {
  const _ParseState._(this.kind);
  final int kind;

  static const _ParseState none = _ParseState._(0);
  static const _ParseState partial = _ParseState._(1);
}

final class _ParsedMessages extends _ParseResult {
  const _ParsedMessages({
    required this.consumed,
    required this.msgs,
  });

  final int consumed;
  final List<Msg> msgs;
}

enum _PrefixMatch {
  none,
  partial,
  full,
}

_PrefixMatch _matchesPrefix(List<int> buffer, List<int> seq) {
  final len = buffer.length < seq.length ? buffer.length : seq.length;
  for (var i = 0; i < len; i++) {
    if (buffer[i] != seq[i]) return _PrefixMatch.none;
  }
  if (buffer.length < seq.length) return _PrefixMatch.partial;
  return _PrefixMatch.full;
}

_ParseResult _tryParseCsi(List<int> buffer) {
  if (buffer.length < 2) return _ParseState.none;
  if (buffer[0] != 0x1b || buffer[1] != 0x5b) return _ParseState.none;

  // X10 mouse (modes 9/1000, terminals without SGR mouse): `ESC [ M Cb Cx
  // Cy` — the 'M' here OPENS a 3-byte payload instead of terminating the
  // CSI. Without this special-case the parser consumes the lone 'M' and
  // the payload bytes leak through as keypresses (mojibake states).
  if (buffer.length >= 3 && buffer[2] == 0x4d) {
    const x10Length = 6;
    final payloadPrintable =
        buffer.length >= x10Length &&
        buffer[3] >= 0x20 &&
        buffer[4] >= 0x20 &&
        buffer[5] >= 0x20;
    if (payloadPrintable) {
      return _ParsedMessages(
        consumed: x10Length,
        msgs: _decodeX10Mouse(buffer[3], buffer[4], buffer[5]),
      );
    }
    if (buffer.length < x10Length &&
        buffer.sublist(3).every((b) => b >= 0x20)) {
      return _ParseState.partial; // payload still arriving
    }
    // Not a mouse payload (e.g. an ESC follows): fall through to the
    // generic path, which consumes the lone 'M' as an unknown sequence.
  }

  var i = 2;
  while (i < buffer.length) {
    final b = buffer[i];
    if (b >= 0x40 && b <= 0x7e) {
      final seq = String.fromCharCodes(buffer.sublist(2, i + 1));
      final msgs = _decodeCsi(seq);
      return _ParsedMessages(consumed: i + 1, msgs: msgs);
    }
    i++;
  }
  return _ParseState.partial;
}

List<Msg> _decodeCsi(String seq) {
  if (seq.endsWith('R')) {
    final body = seq.substring(0, seq.length - 1);
    final parts = body.split(';');
    if (parts.length == 2) {
      final row = int.tryParse(parts[0]);
      final col = int.tryParse(parts[1]);
      if (row != null && col != null) {
        return [
          CursorPositionMsg(
            x: col > 0 ? col - 1 : 0,
            y: row > 0 ? row - 1 : 0,
          ),
        ];
      }
    }
  }

  if (seq.endsWith('\$y')) {
    final body = seq.substring(0, seq.length - 2).replaceFirst('?', '');
    final parts = body.split(';');
    if (parts.length == 2) {
      final mode = int.tryParse(parts[0]);
      final value = int.tryParse(parts[1]);
      if (mode != null && value != null) {
        return [ModeReportMsg(mode: mode, value: value)];
      }
    }
    return const <Msg>[];
  }

  if (seq.startsWith('>') && seq.endsWith('c')) {
    return [TerminalVersionMsg(seq.substring(1, seq.length - 1))];
  }

  if (seq.startsWith('<') && (seq.endsWith('M') || seq.endsWith('m'))) {
    final release = seq.endsWith('m');
    final body = seq.substring(1, seq.length - 1);
    final parts = body.split(';');
    if (parts.length == 3) {
      final cb = int.tryParse(parts[0]);
      final cx = int.tryParse(parts[1]);
      final cy = int.tryParse(parts[2]);
      if (cb != null && cx != null && cy != null) {
        final mouse = Mouse(
          x: cx > 0 ? cx - 1 : 0,
          y: cy > 0 ? cy - 1 : 0,
          button: _mouseButtonFromCb(cb),
          modifiers: _mouseModifiersFromCb(cb),
        );
        if ((cb & 64) != 0) {
          return [MouseWheelMsg(mouse)];
        }
        if ((cb & 32) != 0 && !release) {
          return [MouseMotionMsg(mouse)];
        }
        if (release) {
          return [MouseReleaseMsg(mouse)];
        }
        return [MouseClickMsg(mouse)];
      }
    }
  }

  final keyboard = decodeKittyKeyboard(seq);
  if (keyboard != null) return keyboard;

  return const <Msg>[];
}

_ParseResult _tryParseOsc(List<int> buffer) {
  if (buffer.length < 2) return _ParseState.none;
  if (buffer[0] != 0x1b || buffer[1] != 0x5d) return _ParseState.none;

  var i = 2;
  while (i < buffer.length) {
    final b = buffer[i];
    if (b == 0x07) {
      final seq = String.fromCharCodes(buffer.sublist(2, i));
      return _ParsedMessages(consumed: i + 1, msgs: _decodeOsc(seq));
    }
    if (b == 0x1b) {
      if (i + 1 >= buffer.length) return _ParseState.partial;
      if (buffer[i + 1] == 0x5c) {
        final seq = String.fromCharCodes(buffer.sublist(2, i));
        return _ParsedMessages(consumed: i + 2, msgs: _decodeOsc(seq));
      }
    }
    i++;
  }
  return _ParseState.partial;
}

_ParseResult _tryParseDcs(List<int> buffer) {
  if (buffer.length < 2) return _ParseState.none;
  if (buffer[0] != 0x1b || buffer[1] != 0x50) return _ParseState.none;

  var i = 2;
  while (i < buffer.length) {
    final b = buffer[i];
    if (b == 0x1b) {
      if (i + 1 >= buffer.length) return _ParseState.partial;
      if (buffer[i + 1] == 0x5c) {
        final seq = String.fromCharCodes(buffer.sublist(2, i));
        return _ParsedMessages(consumed: i + 2, msgs: _decodeDcs(seq));
      }
    }
    i++;
  }
  return _ParseState.partial;
}

List<Msg> _decodeDcs(String seq) {
  final marker = seq.indexOf('+r');
  if (marker == -1) return const <Msg>[];
  var payload = seq.substring(marker + 2);
  if (payload.startsWith(';')) {
    payload = payload.substring(1);
  }
  if (payload.isEmpty) return const <Msg>[];

  final eq = payload.indexOf('=');
  if (eq == -1) {
    final name = _decodeHexAscii(payload);
    return [CapabilityMsg(name ?? payload)];
  }

  final nameHex = payload.substring(0, eq);
  final valueHex = payload.substring(eq + 1);
  final name = _decodeHexAscii(nameHex) ?? nameHex;
  final value = _decodeHexAscii(valueHex) ?? valueHex;
  return [CapabilityMsg('$name=$value')];
}

List<Msg> _decodeOsc(String seq) {
  if (seq.startsWith('10;')) {
    final rgb = _parseOscRgb(seq.substring(3));
    if (rgb != null) return [ForegroundColorMsg(rgb)];
    return const <Msg>[];
  }
  if (seq.startsWith('11;')) {
    final rgb = _parseOscRgb(seq.substring(3));
    if (rgb != null) return [BackgroundColorMsg(rgb)];
    return const <Msg>[];
  }
  if (seq.startsWith('12;')) {
    final rgb = _parseOscRgb(seq.substring(3));
    if (rgb != null) return [CursorColorMsg(rgb)];
    return const <Msg>[];
  }

  if (seq.startsWith('52;')) {
    final parts = seq.split(';');
    if (parts.length >= 3) {
      final selection = parts[1];
      final data = parts.sublist(2).join(';');
      final content = _decodeClipboardPayload(data);
      if (content != null) {
        return [
          ClipboardMsg(
            content: content,
            selection: selection == 'p' ? 1 : 0,
          ),
        ];
      }
    }
  }

  return const <Msg>[];
}

String? _decodeHexAscii(String text) {
  if (text.isEmpty || text.length.isOdd) return null;
  final bytes = <int>[];
  for (var i = 0; i < text.length; i += 2) {
    final part = text.substring(i, i + 2);
    final value = int.tryParse(part, radix: 16);
    if (value == null) return null;
    bytes.add(value);
  }
  return utf8.decode(bytes, allowMalformed: true);
}

int? _parseOscRgb(String text) {
  final body = text.startsWith('rgb:') ? text.substring(4) : text;
  final parts = body.split('/');
  if (parts.length != 3) return null;
  final r = int.tryParse(parts[0], radix: 16);
  final g = int.tryParse(parts[1], radix: 16);
  final b = int.tryParse(parts[2], radix: 16);
  if (r == null || g == null || b == null) return null;
  final rr = parts[0].length > 2 ? (r >> (4 * (parts[0].length - 2))) : r;
  final gg = parts[1].length > 2 ? (g >> (4 * (parts[1].length - 2))) : g;
  final bb = parts[2].length > 2 ? (b >> (4 * (parts[2].length - 2))) : b;
  return ((rr & 0xff) << 16) | ((gg & 0xff) << 8) | (bb & 0xff);
}

String? _decodeClipboardPayload(String data) {
  if (data == '?') return null;
  try {
    final decoded = base64Decode(data);
    return utf8.decode(decoded, allowMalformed: true);
  } catch (_) {
    return null;
  }
}

/// Decodes an X10 mouse payload (modes 9/1000): [cbByte]/[cxByte]/[cyByte]
/// are the terminal's 32-offset bytes — button code, column, row.
List<Msg> _decodeX10Mouse(int cbByte, int cxByte, int cyByte) {
  final cb = cbByte - 32;
  final mouse = Mouse(
    x: cxByte >= 33 ? cxByte - 33 : 0,
    y: cyByte >= 33 ? cyByte - 33 : 0,
    button: cb == 3 ? MouseButton.none : _mouseButtonFromCb(cb),
    modifiers: _mouseModifiersFromCb(cb),
  );
  if (cb == 3) return [MouseReleaseMsg(mouse)];
  if ((cb & 64) != 0) return [MouseWheelMsg(mouse)];
  if ((cb & 32) != 0) return [MouseMotionMsg(mouse)];
  return [MouseClickMsg(mouse)];
}

Set<KeyMod> _mouseModifiersFromCb(int cb) {
  final mods = <KeyMod>{};
  if ((cb & 4) != 0) mods.add(KeyMod.shift);
